CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY, email VARCHAR(254) UNIQUE NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'USER', kyc_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', trust_score INTEGER NOT NULL DEFAULT 0, suspended BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS wallets (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id), asset VARCHAR(16) NOT NULL, available NUMERIC(28,10) NOT NULL DEFAULT 0, locked NUMERIC(28,10) NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 0, UNIQUE(user_id, asset), CHECK (available >= 0 AND locked >= 0));
CREATE TABLE IF NOT EXISTS trade_orders (id UUID PRIMARY KEY, maker_id UUID NOT NULL REFERENCES users(id), side VARCHAR(8) NOT NULL, asset VARCHAR(16) NOT NULL, crypto_amount NUMERIC(28,10) NOT NULL, fiat_amount NUMERIC(28,2) NOT NULL, fiat_currency VARCHAR(8) NOT NULL, payment_methods VARCHAR(500) NOT NULL, status VARCHAR(24) NOT NULL, taker_id UUID REFERENCES users(id), version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (crypto_amount > 0 AND fiat_amount > 0));
CREATE TABLE IF NOT EXISTS escrows (id UUID PRIMARY KEY, order_id UUID UNIQUE NOT NULL REFERENCES trade_orders(id), seller_id UUID NOT NULL REFERENCES users(id), buyer_id UUID NOT NULL REFERENCES users(id), asset VARCHAR(16) NOT NULL, amount NUMERIC(28,10) NOT NULL, status VARCHAR(24) NOT NULL, buyer_paid_at TIMESTAMPTZ, seller_received_at TIMESTAMPTZ, resolved_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ledger_entries (id UUID PRIMARY KEY, wallet_id UUID NOT NULL REFERENCES wallets(id), escrow_id UUID REFERENCES escrows(id), entry_type VARCHAR(32) NOT NULL, available_delta NUMERIC(28,10) NOT NULL DEFAULT 0, locked_delta NUMERIC(28,10) NOT NULL DEFAULT 0, idempotency_key VARCHAR(100) UNIQUE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS chat_messages (id UUID PRIMARY KEY, escrow_id UUID NOT NULL REFERENCES escrows(id), sender_id UUID NOT NULL REFERENCES users(id), body VARCHAR(2000) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_orders_active ON trade_orders(status, asset); CREATE INDEX IF NOT EXISTS idx_escrows_parties ON escrows(buyer_id, seller_id);
